              "type": "string",
              "minLength": 1
            },
            "stringFilter": {
              "type": "object",
              "properties": {
                "matchType": {
                  "type": "string",
                  "enum": [
                    "EXACT",
                    "BEGINS_WITH",
                    "ENDS_WITH",
                    "CONTAINS",
                    "FULL_REGEXP",
                    "PARTIAL_REGEXP"
                  ]
                },
                "value": {
                  "type": "string"
                },
                "caseSensitive": {
                  "type": "boolean"
                }
              },
              "required": [
                "matchType",
                "value"
              ],
              "additionalProperties": false
            },
            "inListFilter": {
              "type": "object",
              "properties": {
                "values": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  },
                  "minItems": 1,
                  "maxItems": 1000
                },
                "caseSensitive": {
                  "type": "boolean"
                }
              },
              "required": [
                "values"
              ],
              "additionalProperties": false
            },
            "numericFilter": {
              "type": "object",
              "properties": {
                "operation": {
                  "type": "string",
                  "enum": [
                    "EQUAL",
                    "LESS_THAN",
                    "LESS_THAN_OR_EQUAL",
                    "GREATER_THAN",
                    "GREATER_THAN_OR_EQUAL"
                  ]
                },
                "value": {
                  "oneOf": [
