                        }
                      },
                      "required": [
                        "doubleValue"
                      ],
                      "additionalProperties": false
                    }
                  ]
                }
              },
              "required": [
                "operation",
                "value"
              ],
              "additionalProperties": false
            },
            "emptyFilter": {
              "type": "object",
              "properties": {},
              "required": [],
              "additionalProperties": false
            }
          },
          "required": [
            "fieldName"
          ],
          "additionalProperties": false,
          "oneOf": [
            {
              "required": [
                "stringFilter"
              ]
            },
            {
              "required": [
                "inListFilter"
              ]
            },
            {
              "required": [
                "numericFilter"
              ]
            },
            {
              "required": [
                "emptyFilter"
              ]
            }
          ]
        },
        "andGroup": {
          "type": "object",
          "properties": {
            "expressions": {
              "type": "array",
              "items": {
                "$ref": "#/definitions/ONFGA4FilterExpression"
              },
              "minItems": 1,
              "maxItems": 100
            }
          },
          "required": [
            "expressions"
          ],
          "additionalProperties": false
        },
        "orGroup": {
          "type": "object",
          "properties": {
            "expressions": {
              "type": "array",
              "items": {
                "$ref": "#/definitions/ONFGA4FilterExpression"
              },
              "minItems": 1,
              "maxItems": 100
            }
          },
          "required": [
            "expressions"
          ],
          "additionalProperties": false
        },
        "notExpression": {
          "$ref": "#/definitions/ONFGA4FilterExpression"
        }
      },
      "additionalProperties": false
    }
  }
}
```

